func TestCLI_ArgumentParsing(t *testing.T) {
	tests := []struct {
		name       string
		args       []string
		wantExit   int
		wantStderr string
	}{
		{"no args", []string{}, 2, "Usage:"},
		{"unknown command", []string{"bogus"}, 2, "unknown command"},
		{"get without key", []string{"get"}, 2, "get requires a key"},
		{"set without value", []string{"set", "key"}, 2, "set requires key and value"},
		{"delete without key", []string{"delete"}, 2, "delete requires a key"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
			cli := NewCLI(stdout, stderr, t.TempDir())

			exit := cli.Run(tt.args)

			if exit != tt.wantExit {
				t.Errorf("exit = %d, want %d", exit, tt.wantExit)
			}
			if !bytes.Contains(stderr.Bytes(), []byte(tt.wantStderr)) {
				t.Errorf("stderr = %q, want containing %q", stderr.String(), tt.wantStderr)
			}
		})
	}
}

func TestCLI_Init(t *testing.T) {
	t.Run("creates config file", func(t *testing.T) {
		dir := t.TempDir()
		stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
		cli := NewCLI(stdout, stderr, dir)

		exit := cli.Run([]string{"init"})

		if exit != 0 {
			t.Fatalf("exit = %d, stderr = %s", exit, stderr.String())
		}
		if _, err := os.Stat(filepath.Join(dir, "config.yaml")); err != nil {
			t.Error("config file not created")
		}
	})

	t.Run("fails if exists", func(t *testing.T) {
		dir := t.TempDir()
		configPath := filepath.Join(dir, "config.yaml")
		os.WriteFile(configPath, []byte("existing: true"), 0644)

		stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
		cli := NewCLI(stdout, stderr, dir)

		exit := cli.Run([]string{"init"})

		if exit != 1 {
			t.Errorf("exit = %d, want 1", exit)
		}
	})
}

func TestCLI_GetSetDelete(t *testing.T) {
	dir := t.TempDir()
	stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
	cli := NewCLI(stdout, stderr, dir)

	// Set a value
	if exit := cli.Run([]string{"set", "mykey", "myvalue"}); exit != 0 {
		t.Fatalf("set failed: %s", stderr.String())
	}

	// Get it back
	stdout.Reset()
	if exit := cli.Run([]string{"get", "mykey"}); exit != 0 {
		t.Fatalf("get failed: %s", stderr.String())
	}
	if got := stdout.String(); got != "myvalue\n" {
		t.Errorf("get = %q, want %q", got, "myvalue\n")
	}

	// Delete it
	if exit := cli.Run([]string{"delete", "mykey"}); exit != 0 {
		t.Fatalf("delete failed: %s", stderr.String())
	}

	// Verify gone
	stderr.Reset()
	if exit := cli.Run([]string{"get", "mykey"}); exit != 1 {
		t.Error("get should fail after delete")
	}
}

func TestCLI_Validate(t *testing.T) {
	t.Run("valid yaml", func(t *testing.T) {
		dir := t.TempDir()
		os.WriteFile(filepath.Join(dir, "config.yaml"), []byte("key: value"), 0644)

		stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
		cli := NewCLI(stdout, stderr, dir)

		if exit := cli.Run([]string{"validate"}); exit != 0 {
			t.Errorf("validate failed: %s", stderr.String())
		}
	})

	t.Run("invalid yaml", func(t *testing.T) {
		dir := t.TempDir()
		os.WriteFile(filepath.Join(dir, "config.yaml"), []byte(":::garbage"), 0644)

		stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
		cli := NewCLI(stdout, stderr, dir)

		if exit := cli.Run([]string{"validate"}); exit != 1 {
			t.Error("validate should fail on bad yaml")
		}
	})
}

func TestCLI_OutputFormats(t *testing.T) {
	dir := t.TempDir()
	os.WriteFile(filepath.Join(dir, "config.yaml"), []byte("key: value"), 0644)

	for _, format := range []string{"text", "json", "yaml"} {
		t.Run(format, func(t *testing.T) {
			stdout := &bytes.Buffer{}
			cli := NewCLI(stdout, &bytes.Buffer{}, dir)

			exit := cli.Run([]string{"--format", format, "list"})

			if exit != 0 {
				t.Errorf("list with %s format failed", format)
			}
			if stdout.Len() == 0 {
				t.Error("no output")
			}
		})
	}
}
